  ) AS v(land_code, block, price, geom)
)
INSERT INTO lands (
  residential_id,
  land_code,
  block,
  size,
  price,
  geometry,
  created_at,
  updated_at
)
SELECT
  r.id,
  l.land_code,
  l.block,
  ST_Area(l.geom::geography),
  l.price,
  l.geom::geography,
  NOW(),
  NOW()
FROM new_residential r
CROSS JOIN lot_data l;

COMMIT;

-- Verification queries
-- SELECT id, name, ST_AsText(boundary::geometry) FROM residentials WHERE name = 'Valle Dorado' ORDER BY id DESC LIMIT 1;
-- SELECT land_code, block, ROUND(size::numeric, 2) AS area_m2, ST_IsValid(geometry::geometry) AS valid
-- FROM lands
-- WHERE residential_id = (SELECT id FROM residentials WHERE name = 'Valle Dorado' ORDER BY id DESC LIMIT 1)
-- ORDER BY block, land_code;
